// PUTAWAY_ASYNC_SUBMIT - shared helpers
const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
const list = (x) => (Array.isArray(x) ? x : x ? [x] : []).filter((r) => r);
const digits = (v) => /^[0-9]{1,20}$/.test(s(v));
const num = (v) => Number(v || 0);
// the classic confirmation refuses more than this (Phase 0 guard)
const MAX_OLD_PATH_ROWS = 500;
const answer = (route, code, message, extra) => Object.assign({ route: route, code: String(code), message: message || "" }, extra || {});
const dbAddSeconds = function dbAddSeconds(text, seconds) {
  const m = String(text || "").match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})/);
  if (!m) return "";
  const d = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]), Number(m[4]), Number(m[5]), Number(m[6])) + seconds * 1000);
  const p = (n) => (n < 10 ? "0" : "") + n;
  return d.getUTCFullYear() + "-" + p(d.getUTCMonth() + 1) + "-" + p(d.getUTCDate()) + " " + p(d.getUTCHours()) + ":" + p(d.getUTCMinutes()) + ":" + p(d.getUTCSeconds());
};
// PUTAWAY_ASYNC_SUBMIT - Result: the answer of whichever node ended the run; after the queue writes, the read-back decides
const submitResult = function submitResult(guard, entry, src, back) {
  const e = entry || {};
  const r = src || {};
  const out = { route: s(r.route), code: s(r.code), message: s(r.message), reason: s(r.reason), job_id: s(e.jobId), job_status: s(e.jobStatus), to_id: s(guard.toId),
    to_no: s(e.toNo), row_count: String(num(r.rowCount)), progress_percent: String(num(e.progressPercent)), progress_message: s(e.progressMessage),
    error_code: s(e.errorCode), error_message: s(e.errorMessage), evidence: "" };
  if (back) {
    const b = list(back)[0] || {};
    const ok = digits(b.job_id) && String(b.is_processing) === "1" && s(b.lock_ref) === guard.key;
    Object.assign(out, ok
      ? { route: "QUEUED", code: "200", message: "Queued for processing", job_id: s(b.job_id), job_status: s(b.job_status), progress_percent: "0", progress_message: "Queued for processing" }
      : { route: "STOP", code: "500", message: "The completion could not be queued: please try again.", job_id: s(b.job_id), job_status: s(b.job_status) });
  }
  out.evidence = JSON.stringify({ v: 1, workflow: "PUTAWAY_ASYNC_SUBMIT", operation: s(guard.operation), route: out.route, code: out.code, reason: out.reason });
  return out;
};
